@page "/recipes"
@page "/recipes/{Category}"

<PageTitle>Recipes - @(Category ?? "All Categories")</PageTitle>

<h1>@GetCategoryTitle()</h1>

@if (Category is null)
{
    <p>Select a category to browse recipes:</p>
    <ul>
        <li><a href="recipes/appetizers">Appetizers</a></li>
        <li><a href="recipes/main-courses">Main Courses</a></li>
        <li><a href="recipes/desserts">Desserts</a></li>
    </ul>
}
else
{
    <div class="row">
        @foreach (var recipe in GetRecipesForCategory())
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        <a href="recipes/@Category/@recipe.Slug" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string? Category { get; set; }

    private string GetCategoryTitle() => Category switch
    {
        "appetizers" => "🥗 Appetizers",
        "main-courses" => "🍝 Main Courses",
        "desserts" => "🍰 Desserts",
        _ => "All Recipes"
    };

    private List<RecipeSummary> GetRecipesForCategory() => Category switch
    {
        "appetizers" => new()
        {
            new("Bruschetta", "bruschetta", "Classic Italian tomato and basil topping on crusty bread."),
            new("Spinach Dip", "spinach-dip", "Creamy warm spinach and artichoke dip."),
        },
        "main-courses" => new()
        {
            new("Spaghetti Carbonara", "spaghetti-carbonara", "Rich and creamy Italian pasta with pancetta."),
            new("Grilled Chicken", "grilled-chicken", "Herb-marinated chicken grilled to perfection."),
        },
        "desserts" => new()
        {
            new("Chocolate Cake", "chocolate-cake", "Moist, rich chocolate layer cake with ganache."),
            new("Tiramisu", "tiramisu", "Classic Italian coffee-flavored layered dessert."),
        },
        _ => new()
    };

    private record RecipeSummary(string Title, string Slug, string Description);
}

@page "/recipes/{Category}/{Slug}"

<PageTitle>@GetRecipe().Title - RecipeHub</PageTitle>

@{ var recipe = GetRecipe(); }

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="recipes">Recipes</a></li>
        <li class="breadcrumb-item"><a href="recipes/@Category">@GetCategoryName()</a></li>
        <li class="breadcrumb-item active">@recipe.Title</li>
    </ol>
</nav>

<h1>@recipe.Title</h1>
<p class="lead">@recipe.Description</p>

<h3>Ingredients</h3>
<ul>
    @foreach (var ingredient in recipe.Ingredients)
    {
        <li>@ingredient</li>
    }
</ul>

<h3>Steps</h3>
<ol>
    @foreach (var step in recipe.Steps)
    {
        <li class="mb-2">@step</li>
    }
</ol>

<hr />
<h4>Rate this Recipe</h4>
<StarRating RecipeSlug="@Slug" />

@code {
    [Parameter] public string Category { get; set; } = "";
    [Parameter] public string Slug { get; set; } = "";

    private string GetCategoryName() => Category switch
    {
        "appetizers" => "Appetizers",
        "main-courses" => "Main Courses",
        "desserts" => "Desserts",
        _ => Category
    };

    private RecipeData GetRecipe() => AllRecipes.GetValueOrDefault(Slug) ??
        new("Recipe Not Found", "This recipe could not be found.", new(), new());

    private static readonly Dictionary<string, RecipeData> AllRecipes = new()
    {
        ["bruschetta"] = new(
            "Bruschetta",
            "Classic Italian tomato and basil topping on crusty bread.",
            new() { "4 ripe tomatoes, diced", "Fresh basil leaves", "2 cloves garlic, minced", "Baguette, sliced", "Extra virgin olive oil", "Salt and pepper" },
            new() { "Dice tomatoes and combine with minced garlic and chopped basil.", "Season with salt, pepper, and a drizzle of olive oil.", "Toast baguette slices until golden.", "Spoon tomato mixture onto toast and serve immediately." }
        ),
        ["spinach-dip"] = new(
            "Spinach Dip",
            "Creamy warm spinach and artichoke dip.",
            new() { "10 oz frozen spinach, thawed", "8 oz cream cheese", "1/2 cup sour cream", "1 can artichoke hearts, chopped", "1/2 cup parmesan cheese", "2 cloves garlic, minced" },
            new() { "Preheat oven to 350°F (175°C).", "Squeeze excess water from spinach.", "Mix all ingredients in a bowl until combined.", "Transfer to a baking dish and bake for 25 minutes until bubbly.", "Serve with crackers or bread." }
        ),
        ["spaghetti-carbonara"] = new(
            "Spaghetti Carbonara",
            "Rich and creamy Italian pasta with pancetta.",
            new() { "400g spaghetti", "200g pancetta or guanciale", "4 egg yolks", "100g pecorino romano, grated", "Black pepper" },
            new() { "Cook spaghetti in salted boiling water until al dente.", "Crisp pancetta in a skillet over medium heat.", "Whisk egg yolks with grated pecorino and black pepper.", "Drain pasta, reserving 1 cup pasta water.", "Toss hot pasta with pancetta, then remove from heat and stir in egg mixture.", "Add pasta water as needed for a creamy sauce. Serve immediately." }
        ),
        ["grilled-chicken"] = new(
            "Grilled Chicken",
            "Herb-marinated chicken grilled to perfection.",
            new() { "4 chicken breasts", "3 tbsp olive oil", "2 lemons, juiced", "4 cloves garlic, minced", "Fresh rosemary and thyme", "Salt and pepper" },
            new() { "Combine olive oil, lemon juice, garlic, and herbs for the marinade.", "Marinate chicken for at least 2 hours.", "Preheat grill to medium-high heat.", "Grill chicken 6-7 minutes per side until internal temp reaches 165°F.", "Rest for 5 minutes before serving." }
        ),
        ["chocolate-cake"] = new(
            "Chocolate Cake",
            "Moist, rich chocolate layer cake with ganache.",
            new() { "2 cups flour", "2 cups sugar", "3/4 cup cocoa powder", "2 eggs", "1 cup buttermilk", "1 cup hot coffee", "1/2 cup vegetable oil", "2 tsp vanilla extract" },
            new() { "Preheat oven to 350°F. Grease two 9-inch round pans.", "Mix dry ingredients together, then add wet ingredients.", "Beat for 2 minutes, then stir in hot coffee (batter will be thin).", "Pour into pans and bake 30-35 minutes.", "Cool completely, then frost with chocolate ganache." }
        ),
        ["tiramisu"] = new(
            "Tiramisu",
            "Classic Italian coffee-flavored layered dessert.",
            new() { "6 egg yolks", "3/4 cup sugar", "500g mascarpone cheese", "2 cups heavy cream", "2 cups strong espresso, cooled", "3 tbsp coffee liqueur", "Ladyfinger biscuits", "Cocoa powder" },
            new() { "Whisk egg yolks and sugar until thick and pale.", "Fold in mascarpone cheese until smooth.", "Whip heavy cream to stiff peaks, then fold into mascarpone mixture.", "Mix cooled espresso with coffee liqueur.", "Dip ladyfingers briefly in coffee mixture and layer in dish.", "Spread half the cream mixture over ladyfingers. Repeat layers.", "Refrigerate at least 4 hours. Dust with cocoa powder before serving." }
        ),
    };

    private record RecipeData(string Title, string Description, List<string> Ingredients, List<string> Steps);
}

@rendermode InteractiveServer

<div class="star-rating" aria-label="Rate this recipe">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= CurrentRating ? "filled" : "")"
              @onclick="() => SetRating(star)"
              role="button"
              aria-label="@star stars">
            @(star <= CurrentRating ? "★" : "☆")
        </span>
    }
    @if (CurrentRating > 0)
    {
        <span class="ms-2 text-muted">You rated this @CurrentRating/5</span>
    }
</div>

@code {
    [Parameter]
    public string RecipeSlug { get; set; } = "";

    private int CurrentRating { get; set; }

    private void SetRating(int rating)
    {
        CurrentRating = rating;
    }
}

.star-rating {
    font-size: 1.5rem;
}

.star {
    cursor: pointer;
    color: #ccc;
    transition: color 0.2s;
}

.star:hover,
.star.filled {
    color: #ffc107;
}

@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community.</p>

@if (IsSubmitted)
{
    <div class="alert alert-success">
        <h4>Thank you!</h4>
        <p>Your recipe "<strong>@Model.Title</strong>" has been submitted for review.</p>
        <button class="btn btn-primary" @onclick="ResetForm">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="Model.Title" />
            <ValidationMessage For="() => Model.Title" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="Model.Ingredients" />
            <ValidationMessage For="() => Model.Ingredients" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="Model.Steps" />
            <ValidationMessage For="() => Model.Steps" />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeSubmission Model { get; set; } = new();
    private bool IsSubmitted { get; set; }

    private void HandleSubmit()
    {
        IsSubmitted = true;
    }

    private void ResetForm()
    {
        Model = new();
        IsSubmitted = false;
    }

    private class RecipeSubmission
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required.")]
        [System.ComponentModel.DataAnnotations.StringLength(100, ErrorMessage = "Title must be 100 characters or fewer.")]
        public string Title { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Ingredients are required.")]
        public string Ingredients { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Steps are required.")]
        public string Steps { get; set; } = "";
    }
}

